package vip.xiaonuo.srm.sourcing;
import java.util.*;
import java.time.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.context.event.EventListener;
import org.springframework.transaction.annotation.*;
import vip.xiaonuo.flow.api.*;
import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;
import static vip.xiaonuo.srm.sourcing.SourcingStore.*;
import static vip.xiaonuo.srm.sourcing.SourcingRules.*;
import static vip.xiaonuo.srm.sourcing.SourcingInputs.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED)
public class SourcingAwardService {
 private final SourcingStore x;private final SourcingComparison comparison;private final SrmFlowApi flow;
 private Map<String,Object> award(String aid,boolean lock){var rows=x.db.queryForList("SELECT * FROM SRM_SRC_AWARD WHERE ID=?"+(lock?" FOR UPDATE":""),aid);require(rows.size()==1,404,"定点申请不存在或无权访问");return rows.get(0);}
 private Map<String,Object> basis(Map<String,Object> a){return x.object(x.crypto.decrypt(s(a,"SNAPSHOT_CIPHER")));}
 private boolean noHistory(Map<String,Object> b){return Boolean.TRUE.equals(((Map<?,?>)b.get("performance")).get("requiresApprovedException"));}
 private boolean risky(Map<String,Object> b){return Set.of("UNKNOWN","HIGH").contains(String.valueOf(((Map<?,?>)b.get("risk")).get("level")));}
 public Map<String,Object> submit(Context a,String rid,Award p){x.writer(a);x.access.requireSupplier(a,p.supplierId(),true);var r=x.rfq(a,rid,true);String hash=x.hash(p);var old=x.db.queryForList("SELECT * FROM SRM_SRC_AWARD WHERE RFQ_ID=? AND REQUEST_KEY=?",rid,p.requestKey());if(!old.isEmpty()){require(hash.equals(old.get(0).get("REQUEST_HASH"))&&a.userId().equals(old.get(0).get("CREATED_BY")),409,"定点请求键内容冲突");return detail(a,s(old.get(0),"ID"));}
  require(s(r,"STATUS").equals("CLOSED"),409,"须先截止封盘，再提交定点审批");x.qualified(a,p.supplierId(),s(r,"ORG_ID"),false);x.eligibility.requireEligibleForAward(p.supplierId(),s(r,"ORG_ID"));require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_SRC_AWARD WHERE RFQ_ID=? AND STATUS IN ('PENDING','APPROVED','PUBLISHED')",Long.class,rid)==0,409,"已有有效定点申请");
  var basis=comparison.basis(a,r,p.supplierId(),YearMonth.now(ZoneId.of("Asia/Shanghai")).minusMonths(1));require(!noHistory(x.object(x.json(basis)))||p.noHistoryReason()!=null&&!p.noHistoryReason().isBlank(),400,"无绩效历史须填写定点例外原因");require(flow.definitions().stream().anyMatch(d->d.get("key").equals("srm_award")&&!Boolean.TRUE.equals(d.get("suspended"))),409,"定点流程未发布或已挂起");String aid=id();String pid=flow.start("srm_award",aid,Map.of("approvalId",aid,"rfqId",rid,"orgId",s(r,"ORG_ID"),"requestedBy",a.userId(),"businessType","AWARD"));
  x.db.update("INSERT INTO SRM_SRC_AWARD(ID,RFQ_ID,SUPPLIER_ID,PROCESS_ID,STATUS,SNAPSHOT_CIPHER,BASIS_HASH,REASON,NO_HISTORY_REASON,DISCLOSE_LOSS,CREATED_BY,CREATED_AT,REQUEST_KEY,REQUEST_HASH) VALUES(?,?,?,?,'PENDING',?,?,?,?,?,?,NOW(3),?,?)",aid,rid,p.supplierId(),pid,x.crypto.encrypt(x.json(basis)),x.hash(basis),p.reason(),p.noHistoryReason(),p.discloseLoss(),a.userId(),p.requestKey(),hash);
  x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='AWARD_PENDING',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",rid);x.audit(a,r,p.supplierId(),aid,"AWARD_SUBMITTED",Map.of("processId",pid,"basisHash",x.hash(basis)));x.event(rid);return detail(a,aid);
 }
 public Map<String,Object> detail(Context a,String aid){require(!a.portal(),403,"门户仅可查看已发布的本方定点结果");var ar=award(aid,false);var r=x.rfq(a,s(ar,"RFQ_ID"),false);var out=new LinkedHashMap<String,Object>();for(String[] f:new String[][]{{"id","ID"},{"rfqId","RFQ_ID"},{"supplierId","SUPPLIER_ID"},{"status","STATUS"},{"reason","REASON"},{"noHistoryReason","NO_HISTORY_REASON"},{"createdBy","CREATED_BY"},{"reviewComment","REVIEW_COMMENT"},{"discloseLoss","DISCLOSE_LOSS"}})out.put(f[0],ar.get(f[1]));out.put("rfqTitle",r.get("TITLE"));out.put("basis",basis(ar));out.put("tasks",flow.tasks(s(ar,"PROCESS_ID")));out.put("actions",x.db.queryForList("SELECT ACTION AS action,ACTOR_ID AS actorId,TARGET_ID AS targetId,COMMENT AS comment,CREATED_AT AS createdAt FROM SRM_SRC_AWARD_ACTION WHERE AWARD_ID=? ORDER BY CREATED_AT,ID",aid));out.put("reviewers",x.access.sourcingReviewers(s(r,"ORG_ID"),s(ar,"CREATED_BY"),s(r,"CREATED_BY")));return out;}
 public List<Map<String,Object>> list(Context a,String rid){require(!a.portal(),403,"门户不能查看内部定点申请");x.rfq(a,rid,false);return x.db.queryForList("SELECT ID AS id,STATUS AS status,SUPPLIER_ID AS supplierId,CREATED_AT AS createdAt FROM SRM_SRC_AWARD WHERE RFQ_ID=? ORDER BY CREATED_AT DESC,ID DESC",rid);}
 private boolean canReview(Context a,Map<String,Object> ar,Map<String,Object> task){return !a.portal()&&!a.userId().equals(ar.get("CREATED_BY"))&&(a.roles().contains("CAT-MGR")||a.roles().contains("superAdmin"))&&(s(task,"assignee").isBlank()||a.userId().equals(task.get("assignee")));}
 public List<Map<String,Object>> tasks(Context a){require(!a.portal(),403,"门户无内部定点待办");var out=new ArrayList<Map<String,Object>>();for(var ar:x.db.queryForList("SELECT * FROM SRM_SRC_AWARD WHERE STATUS='PENDING' ORDER BY CREATED_AT LIMIT 1000")){Map<String,Object> r;try{r=x.rfq(a,s(ar,"RFQ_ID"),false);}catch(vip.xiaonuo.common.exception.CommonException e){if(e.getCode()==404)continue;throw e;}for(var task:flow.tasks(s(ar,"PROCESS_ID")))if(canReview(a,ar,task)){var t=new LinkedHashMap<String,Object>(task);t.put("awardId",ar.get("ID"));t.put("rfqId",ar.get("RFQ_ID"));t.put("title",r.get("TITLE"));t.put("supplierId",ar.get("SUPPLIER_ID"));out.add(t);}}return out;}
 private void validateBasis(Context a,Map<String,Object> r,Map<String,Object> ar){var old=basis(ar);String period=String.valueOf(old.get("performanceEndPeriod"));require(period.equals(YearMonth.now(ZoneId.of("Asia/Shanghai")).minusMonths(1).toString()),409,"绩效窗口已变化，请撤回后重新提交");var fresh=comparison.basis(a,r,s(ar,"SUPPLIER_ID"),YearMonth.parse(period));require(x.hash(fresh).equals(ar.get("BASIS_HASH")),409,"报价、绩效或风险依据已变化，任务保留，请撤回并重新评审");}
 public Map<String,Object> decide(Context a,String aid,String tid,Decision p){var first=award(aid,false);var lockIds=new TreeSet<String>();lockIds.add(s(first,"SUPPLIER_ID"));if(p.action().equals("REASSIGN")&&p.targetId()!=null)lockIds.add(p.targetId());for(String sid:lockIds)x.access.requireSupplier(a,sid,true);var r=x.rfq(a,s(first,"RFQ_ID"),true);var ar=award(aid,true);require(s(ar,"STATUS").equals("PENDING"),409,"申请已处理");var task=flow.task(tid);require(flow.tasks(s(ar,"PROCESS_ID")).stream().anyMatch(t->tid.equals(t.get("id"))),404,"任务不属于本申请");require(canReview(a,ar,task),403,"无审批权限或不能审批本人申请");
  if(p.action().equals("TRANSFER")){require(p.targetId()!=null&&!a.userId().equals(p.targetId())&&x.access.sourcingReviewers(s(r,"ORG_ID"),s(ar,"CREATED_BY"),s(r,"CREATED_BY")).stream().anyMatch(t->p.targetId().equals(t.get("id"))),403,"转办人不具备本组织审批权限");flow.transfer(tid,p.targetId());}
  else if(p.action().equals("REJECT")){flow.stop(s(ar,"PROCESS_ID"),"REJECTED");x.db.update("UPDATE SRM_SRC_AWARD SET STATUS='REJECTED',REVIEWED_BY=?,REVIEW_COMMENT=? WHERE ID=?",a.userId(),p.comment(),aid);x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='CLOSED',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",r.get("ID"));}
  else if(p.action().equals("REASSIGN")){require(p.targetId()!=null&&!p.targetId().equals(ar.get("SUPPLIER_ID")),400,"请选择其他候选供应商");flow.stop(s(ar,"PROCESS_ID"),"REASSIGNED");x.db.update("UPDATE SRM_SRC_AWARD SET STATUS='REASSIGNED',REVIEWED_BY=?,REVIEW_COMMENT=? WHERE ID=?",a.userId(),p.comment(),aid);x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='CLOSED',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",r.get("ID"));recordAction(a,ar,tid,p);x.audit(a,r,s(ar,"SUPPLIER_ID"),aid,"AWARD_REASSIGNED",Map.of("targetSupplierId",p.targetId()));return submit(a,s(r,"ID"),new Award(p.targetId(),UUID.randomUUID().toString(),p.comment(),p.noHistoryReason(),Boolean.TRUE.equals(ar.get("DISCLOSE_LOSS"))));}
  else{require(p.action().equals("APPROVE"),400,"未知审批动作");x.qualified(a,s(ar,"SUPPLIER_ID"),s(r,"ORG_ID"),false);x.eligibility.requireEligibleForAward(s(ar,"SUPPLIER_ID"),s(r,"ORG_ID"));validateBasis(a,r,ar);var basis=basis(ar);require(!noHistory(basis)||p.approveNoHistory(),400,"须明确批准无历史绩效例外");require(!risky(basis)||p.acknowledgeRisk(),400,"须明确确认HIGH或UNKNOWN风险");x.db.update("UPDATE SRM_SRC_AWARD SET REVIEWED_BY=?,REVIEW_COMMENT=? WHERE ID=?",a.userId(),p.comment(),aid);flow.complete(tid,Map.of("decisionActor",a.userId()));require(flow.ended(s(ar,"PROCESS_ID")),409,"审批仍有未完成节点");}
  recordAction(a,ar,tid,p);x.audit(a,r,s(ar,"SUPPLIER_ID"),aid,"AWARD_"+p.action(),Map.of("taskId",tid));x.event(s(r,"ID"));return detail(a,aid);
 }
 private void recordAction(Context a,Map<String,Object> ar,String tid,Decision p){x.db.update("INSERT INTO SRM_SRC_AWARD_ACTION VALUES(?,?,?,?,?,?,?,NOW(3))",id(),ar.get("ID"),tid,p.action(),a.userId(),p.targetId(),p.comment());}
 @EventListener public void completed(SrmFlowCompleted e){var rows=x.db.queryForList("SELECT * FROM SRM_SRC_AWARD WHERE ID=?",e.approvalId());if(rows.isEmpty())return;var first=rows.get(0);var r=x.trusted(s(first,"RFQ_ID"),true);var ar=award(e.approvalId(),true);require(s(ar,"PROCESS_ID").equals(e.processId())&&s(ar,"STATUS").equals("PENDING")&&e.actorId().equals(ar.get("REVIEWED_BY")),409,"定点流程回写关联不一致");x.db.update("UPDATE SRM_SRC_AWARD SET STATUS='APPROVED' WHERE ID=?",ar.get("ID"));x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='AWARD_APPROVED',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",r.get("ID"));}
 public Map<String,Object> publish(Context a,String aid){x.writer(a);var first=award(aid,false);x.access.requireSupplier(a,s(first,"SUPPLIER_ID"),true);var r=x.rfq(a,s(first,"RFQ_ID"),true);var ar=award(aid,true);if(s(ar,"STATUS").equals("PUBLISHED"))return detail(a,aid);require(s(ar,"STATUS").equals("APPROVED"),409,"仅审批通过的定点可发布");x.qualified(a,s(ar,"SUPPLIER_ID"),s(r,"ORG_ID"),false);x.eligibility.requireEligibleForAward(s(ar,"SUPPLIER_ID"),s(r,"ORG_ID"));validateBasis(a,r,ar);
  x.db.update("UPDATE SRM_SRC_AWARD SET STATUS='PUBLISHED',PUBLISHED_AT=NOW(3) WHERE ID=?",aid);x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='AWARDED',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",r.get("ID"));for(String sid:x.invited(s(r,"ID"))){boolean won=sid.equals(ar.get("SUPPLIER_ID"));x.notice(s(r,"ID"),sid,won?"WON":"LOST",won?"本轮定点已中选，请查看本方结果":Boolean.TRUE.equals(ar.get("DISCLOSE_LOSS"))?"本轮未中选。评审意见："+s(ar,"REVIEW_COMMENT"):"本轮未中选，感谢参与");}x.audit(a,r,s(ar,"SUPPLIER_ID"),aid,"AWARD_PUBLISHED",Map.of("discloseLoss",ar.get("DISCLOSE_LOSS")));x.event(s(r,"ID"));return detail(a,aid);
 }
 public void withdraw(Context a,String aid){x.writer(a);var first=award(aid,false);var r=x.rfq(a,s(first,"RFQ_ID"),true);var ar=award(aid,true);require(a.userId().equals(ar.get("CREATED_BY"))||a.roles().contains("superAdmin"),403,"仅申请人可撤回");require(Set.of("PENDING","APPROVED").contains(s(ar,"STATUS")),409,"当前申请不可撤回");if(!flow.ended(s(ar,"PROCESS_ID")))flow.stop(s(ar,"PROCESS_ID"),"WITHDRAWN");x.db.update("UPDATE SRM_SRC_AWARD SET STATUS='WITHDRAWN' WHERE ID=?",aid);x.db.update("UPDATE SRM_SRC_RFQ SET STATUS='CLOSED',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",r.get("ID"));x.audit(a,r,s(ar,"SUPPLIER_ID"),aid,"AWARD_WITHDRAWN",Map.of());x.event(s(r,"ID"));}
 public Map<String,Object> result(Context a,String rid){require(a.portal(),403,"内部请查看定点审批记录");x.rfq(a,rid,false);var rows=x.db.queryForList("SELECT * FROM SRM_SRC_AWARD WHERE RFQ_ID=? AND STATUS='PUBLISHED'",rid);if(rows.isEmpty())return Map.of("published",false);var ar=rows.get(0);boolean won=a.supplierId().equals(ar.get("SUPPLIER_ID"));var result=new LinkedHashMap<String,Object>();result.put("published",true);result.put("won",won);result.put("publishedAt",ar.get("PUBLISHED_AT"));result.put("message",won?"本轮定点已中选":Boolean.TRUE.equals(ar.get("DISCLOSE_LOSS"))?s(ar,"REVIEW_COMMENT"):"本轮未中选，感谢参与");return result;}
}
